// Postgres schema. Tables live in their own `app` schema rather than
// `public`, so Supabase's auto-generated Data API (and its public anon key)
// can't reach them; only the server, connecting as its own role, can.
//
// Every business table is scoped by account_id (a "workspace"), which is what
// later lets one agency user manage many client sub-accounts.
const SCHEMA = `
CREATE SCHEMA IF NOT EXISTS app;
SET search_path TO app, public;

CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS users (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS accounts (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  from_name TEXT NOT NULL DEFAULT '',
  from_email TEXT NOT NULL DEFAULT '',
  stripe_secret_key TEXT NOT NULL DEFAULT '',
  stripe_webhook_secret TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS memberships (
  user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  role TEXT NOT NULL DEFAULT 'owner',
  PRIMARY KEY (user_id, account_id)
);

CREATE TABLE IF NOT EXISTS sessions (
  token TEXT PRIMARY KEY,
  user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  expires_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS contacts (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  first_name TEXT NOT NULL DEFAULT '',
  last_name TEXT NOT NULL DEFAULT '',
  phone TEXT NOT NULL DEFAULT '',
  tags TEXT NOT NULL DEFAULT '[]',
  source TEXT NOT NULL DEFAULT 'manual',
  unsubscribed INT NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Funnel tree: each page has a "yes" exit (form submitted, purchase, Next
-- button) and a "no" exit ("No thanks" button), plus a spot on the canvas.
CREATE TABLE IF NOT EXISTS funnels (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  entry_step_id INT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS funnel_steps (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  funnel_id INT NOT NULL REFERENCES funnels(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  slug TEXT NOT NULL,
  position INT NOT NULL,
  blocks TEXT NOT NULL DEFAULT '[]',
  settings TEXT NOT NULL DEFAULT '{}',
  next_step_id INT,
  no_step_id INT,
  x DOUBLE PRECISION,
  y DOUBLE PRECISION,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (funnel_id, slug)
);

CREATE TABLE IF NOT EXISTS page_events (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  funnel_id INT NOT NULL REFERENCES funnels(id) ON DELETE CASCADE,
  step_id INT NOT NULL REFERENCES funnel_steps(id) ON DELETE CASCADE,
  type TEXT NOT NULL,
  contact_id INT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_events_account ON page_events(account_id, created_at);
CREATE INDEX IF NOT EXISTS idx_events_step ON page_events(step_id);
CREATE INDEX IF NOT EXISTS idx_events_funnel ON page_events(funnel_id);

CREATE TABLE IF NOT EXISTS broadcasts (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  tag TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'draft',
  sent_count INT NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  sent_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS email_log (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  broadcast_id INT REFERENCES broadcasts(id) ON DELETE SET NULL,
  contact_id INT REFERENCES contacts(id) ON DELETE SET NULL,
  to_email TEXT NOT NULL,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  status TEXT NOT NULL,
  error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS products (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  price_cents INT NOT NULL,
  currency TEXT NOT NULL DEFAULT 'usd',
  billing TEXT NOT NULL DEFAULT 'one_time',
  tag TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS orders (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  product_id INT REFERENCES products(id) ON DELETE SET NULL,
  product_name TEXT NOT NULL,
  contact_id INT REFERENCES contacts(id) ON DELETE SET NULL,
  email TEXT NOT NULL DEFAULT '',
  amount_cents INT NOT NULL,
  currency TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  mode TEXT NOT NULL,
  stripe_session_id TEXT,
  funnel_id INT REFERENCES funnels(id) ON DELETE SET NULL,
  step_id INT REFERENCES funnel_steps(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  paid_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_orders_account ON orders(account_id, created_at);

-- Sales pipelines: a board of ordered stages holding deals. A deal is open
-- while it moves through the stages, then marked won or lost (it keeps the
-- stage it was in, so you can see where deals close or drop out).
CREATE TABLE IF NOT EXISTS pipelines (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS pipeline_stages (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  pipeline_id INT NOT NULL REFERENCES pipelines(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  position INT NOT NULL
);

CREATE TABLE IF NOT EXISTS deals (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  pipeline_id INT NOT NULL REFERENCES pipelines(id) ON DELETE CASCADE,
  stage_id INT NOT NULL REFERENCES pipeline_stages(id),
  contact_id INT REFERENCES contacts(id) ON DELETE SET NULL,
  title TEXT NOT NULL,
  value_cents INT NOT NULL DEFAULT 0,
  currency TEXT NOT NULL DEFAULT 'usd',
  status TEXT NOT NULL DEFAULT 'open',
  position INT NOT NULL DEFAULT 0,
  notes TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  closed_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_stages_pipeline ON pipeline_stages(pipeline_id, position);
CREATE INDEX IF NOT EXISTS idx_deals_pipeline ON deals(pipeline_id, stage_id, position);
CREATE INDEX IF NOT EXISTS idx_deals_contact ON deals(contact_id);

-- ---------- Solo marketing app (people, events, levers) ----------
-- A contact is a Person: one record per human across store, newsletter,
-- podcast and inquiries. Email is optional (print-only subscribers), but when
-- present it's unique per workspace, and it's how duplicates merge.
-- Stage (audience, lead, customer, regular) is derived from their events.
ALTER TABLE contacts DROP CONSTRAINT IF EXISTS contacts_account_id_email_key;
CREATE UNIQUE INDEX IF NOT EXISTS idx_contacts_email ON contacts(account_id, email) WHERE email <> '';
ALTER TABLE contacts ADD COLUMN IF NOT EXISTS stage TEXT NOT NULL DEFAULT 'audience';
ALTER TABLE contacts ADD COLUMN IF NOT EXISTS address1 TEXT NOT NULL DEFAULT '';
ALTER TABLE contacts ADD COLUMN IF NOT EXISTS address2 TEXT NOT NULL DEFAULT '';
ALTER TABLE contacts ADD COLUMN IF NOT EXISTS city TEXT NOT NULL DEFAULT '';
ALTER TABLE contacts ADD COLUMN IF NOT EXISTS region TEXT NOT NULL DEFAULT '';
ALTER TABLE contacts ADD COLUMN IF NOT EXISTS postal TEXT NOT NULL DEFAULT '';
ALTER TABLE contacts ADD COLUMN IF NOT EXISTS country TEXT NOT NULL DEFAULT '';

-- Everything that happens to a person. Lever metrics are computed from here.
-- person_id is empty only for anonymous events (a QR scan, a page visit).
CREATE TABLE IF NOT EXISTS events (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  person_id INT REFERENCES contacts(id) ON DELETE CASCADE,
  type TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT '',
  value_cents INT NOT NULL DEFAULT 0,
  campaign_id INT,
  occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  meta TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX IF NOT EXISTS idx_pevents_account ON events(account_id, type, occurred_at);
CREATE INDEX IF NOT EXISTS idx_pevents_person ON events(person_id, occurred_at);

-- Orders come from funnels (checkout) or are imported from the store, Etsy, PayPal.
ALTER TABLE orders ADD COLUMN IF NOT EXISTS source TEXT NOT NULL DEFAULT 'funnel';
ALTER TABLE orders ADD COLUMN IF NOT EXISTS items TEXT NOT NULL DEFAULT '[]';
ALTER TABLE orders ADD COLUMN IF NOT EXISTS external_id TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS idx_orders_external ON orders(account_id, source, external_id) WHERE external_id IS NOT NULL;

-- Newsletter subscriptions, print or email.
CREATE TABLE IF NOT EXISTS subscriptions (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  person_id INT NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,
  product TEXT NOT NULL DEFAULT 'Newsletter',
  format TEXT NOT NULL DEFAULT 'email',
  status TEXT NOT NULL DEFAULT 'active',
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ended_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_subs_person ON subscriptions(person_id);
CREATE INDEX IF NOT EXISTS idx_subs_account ON subscriptions(account_id, status);

-- A campaign is one piece of outreach for one lever: a weekly move, a
-- repurposed post, a printed mailer. Drafts are approved before sending.
CREATE TABLE IF NOT EXISTS campaigns (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  lever TEXT NOT NULL,
  channel TEXT NOT NULL DEFAULT 'email',
  status TEXT NOT NULL DEFAULT 'draft',
  title TEXT NOT NULL DEFAULT '',
  subject TEXT NOT NULL DEFAULT '',
  draft_body TEXT NOT NULL DEFAULT '',
  audience TEXT NOT NULL DEFAULT '[]',
  move TEXT NOT NULL DEFAULT '{}',
  week DATE,
  results TEXT NOT NULL DEFAULT '{}',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  sent_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_campaigns_account ON campaigns(account_id, created_at);
-- One weekly move per workspace per week.
CREATE UNIQUE INDEX IF NOT EXISTS idx_campaigns_week_move ON campaigns(account_id, week) WHERE move <> '{}';

-- Simple follow-ups: when <trigger> happened <delay_days> ago, send this.
CREATE TABLE IF NOT EXISTS automations (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  key TEXT NOT NULL DEFAULT '',
  name TEXT NOT NULL,
  lever TEXT NOT NULL,
  trigger TEXT NOT NULL,
  delay_days INT NOT NULL,
  subject TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL DEFAULT '',
  enabled INT NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS automation_sends (
  automation_id INT NOT NULL REFERENCES automations(id) ON DELETE CASCADE,
  person_id INT NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,
  trigger_key TEXT NOT NULL,
  sent_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (automation_id, person_id, trigger_key)
);

-- Dashboard layout per lever ('all', 'lead', 'conversion', 'upsell', 'continuity').
CREATE TABLE IF NOT EXISTS layouts (
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  lever TEXT NOT NULL,
  tiles TEXT NOT NULL DEFAULT '[]',
  PRIMARY KEY (account_id, lever)
);

-- Owner settings live on the account: voice profile, digest day, focus pin.
ALTER TABLE accounts ADD COLUMN IF NOT EXISTS voice_samples TEXT NOT NULL DEFAULT '[]';
ALTER TABLE accounts ADD COLUMN IF NOT EXISTS voice_notes TEXT NOT NULL DEFAULT '';
ALTER TABLE accounts ADD COLUMN IF NOT EXISTS digest_day INT NOT NULL DEFAULT 1;
ALTER TABLE accounts ADD COLUMN IF NOT EXISTS pinned_lever TEXT NOT NULL DEFAULT '';
ALTER TABLE accounts ADD COLUMN IF NOT EXISTS integrations TEXT NOT NULL DEFAULT '{}';
ALTER TABLE accounts ADD COLUMN IF NOT EXISTS last_digest_at TIMESTAMPTZ;

-- ---------- Workflows: triggers, waits, emails and actions on one map ----------
-- graph is a tree of steps: { nodes: { id: { type, config, next, yes, no } }, root }.
-- An email sequence is simply a run of email and wait steps in a workflow.
CREATE TABLE IF NOT EXISTS workflows (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  lever TEXT NOT NULL DEFAULT 'continuity',
  status TEXT NOT NULL DEFAULT 'draft',
  template TEXT NOT NULL DEFAULT '',
  funnel_id INT REFERENCES funnels(id) ON DELETE SET NULL,
  graph TEXT NOT NULL DEFAULT '{}',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_workflows_account ON workflows(account_id, status);

-- One run per person going through a workflow; node_id is where they are now.
CREATE TABLE IF NOT EXISTS workflow_runs (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  workflow_id INT NOT NULL REFERENCES workflows(id) ON DELETE CASCADE,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  person_id INT NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,
  trigger_key TEXT NOT NULL DEFAULT '',
  node_id TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  wake_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  waiting_on TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (workflow_id, person_id, trigger_key)
);
CREATE INDEX IF NOT EXISTS idx_runs_due ON workflow_runs(status, wake_at);
CREATE INDEX IF NOT EXISTS idx_runs_workflow ON workflow_runs(workflow_id, node_id);

-- Each step a run passed through (powers the "sent", "waiting" counts on the map).
CREATE TABLE IF NOT EXISTS workflow_log (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  run_id INT NOT NULL REFERENCES workflow_runs(id) ON DELETE CASCADE,
  workflow_id INT NOT NULL REFERENCES workflows(id) ON DELETE CASCADE,
  node_id TEXT NOT NULL,
  outcome TEXT NOT NULL,
  detail TEXT NOT NULL DEFAULT '',
  at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_wflog_workflow ON workflow_log(workflow_id, node_id);

ALTER TABLE accounts ADD COLUMN IF NOT EXISTS workflows_seeded INT NOT NULL DEFAULT 0;
-- Email tracking: which workflow or campaign sent it, and when it was opened or clicked.
ALTER TABLE email_log ADD COLUMN IF NOT EXISTS workflow_id INT;
ALTER TABLE email_log ADD COLUMN IF NOT EXISTS campaign_id INT;
ALTER TABLE email_log ADD COLUMN IF NOT EXISTS opened_at TIMESTAMPTZ;
ALTER TABLE email_log ADD COLUMN IF NOT EXISTS clicked_at TIMESTAMPTZ;

-- Short links for printed pieces (QR codes); scans and visits are events.
CREATE TABLE IF NOT EXISTS links (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  code TEXT NOT NULL UNIQUE,
  url TEXT NOT NULL,
  label TEXT NOT NULL DEFAULT '',
  campaign_id INT REFERENCES campaigns(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Email sign-in links (only a hash of the token is stored).
CREATE TABLE IF NOT EXISTS magic_links (
  token_hash TEXT PRIMARY KEY,
  user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at TIMESTAMPTZ NOT NULL,
  used_at TIMESTAMPTZ
);
`;

module.exports = { SCHEMA };
